param([Parameter(Mandatory)][string]$ImmutableRoot,[Parameter(Mandatory)][string]$WorkRoot)
$ErrorActionPreference='Stop';$audit=$PSScriptRoot; $null=New-Item -Force -ItemType Directory $WorkRoot
Copy-Item (Join-Path $ImmutableRoot '*') $WorkRoot -Recurse -Force
function Run([string]$file,[string[]]$argv,[string]$out){$o=Join-Path $out 'stdout.txt';$e=Join-Path $out 'stderr.txt';$c=Join-Path $out 'command.txt';$x=Join-Path $out 'exit.txt';New-Item -Force -ItemType Directory $out|Out-Null;Set-Content $c ((Get-Command pwsh).Source+' -NoProfile -File '+$file+' '+($argv -join ' '));& pwsh -NoProfile -File $file @argv 1>$o 2>$e;$ec=$LASTEXITCODE;Set-Content $x $ec;return $ec}
$sem=Join-Path $WorkRoot 'results\semantic-verifier.txt';& pwsh -NoProfile -File (Join-Path $audit 'SemanticVerifier.ps1') -WorkRoot $WorkRoot -ResultPath $sem|Out-File (Join-Path $WorkRoot 'results\semantic.stdout.txt') -Encoding utf8; if($LASTEXITCODE){throw 'SemanticVerifier baseline failed'}
$rt=Join-Path $WorkRoot 'runtime\runtime-verifier-result.txt';& pwsh -NoProfile -File (Join-Path $audit 'RuntimeOracleVerifier.ps1') -WorkRoot $WorkRoot -ResultPath $rt|Out-File (Join-Path $WorkRoot 'runtime\runtime-verifier.stdout.txt') -Encoding utf8;if($LASTEXITCODE){throw 'RuntimeOracleVerifier baseline failed'}
