$fields += $fields[0..11]
$rows=@('CaseId`tDescription`tVerifier`tTargetArtifact`tMutation`tBaselineExit`tMutationExit`tExpectedFailureTag`tObservedFailureTags`tDetected');$i=0
foreach($f in $fields){$i++;$id='{0:D2}'-f$i;$d=Join-Path $WorkRoot "mutation\cases\$id";$base=Join-Path $d baseline;$mut=Join-Path $d mutation;New-Item -Force -ItemType Directory $base,$mut|Out-Null;$src=Join-Path $WorkRoot "audit\$($f[0])";$tmp=Join-Path $d $f[0];Copy-Item $src $tmp;Run (Join-Path $audit 'MutationVerifier.ps1') @('-Artifact',$tmp) $base|Out-Null;$be=[int](Get-Content (Join-Path $base 'exit.txt'));$mt=Join-Path $d mutation;Copy-Item $tmp (Join-Path $mt $f[0]);$z=Get-Content (Join-Path $mt $f[0])-Raw;$z=$z.Replace($f[1],$f[2]);[IO.File]::WriteAllText((Join-Path $mt $f[0]),$z);Run (Join-Path $audit 'MutationVerifier.ps1') @('-Artifact',(Join-Path $mt $f[0])) $mut|Out-Null;$me=[int](Get-Content (Join-Path $mut 'exit.txt'));$raw=(Get-Content (Join-Path $mut 'stdout.txt') -Raw)+(Get-Content (Join-Path $mut 'stderr.txt') -Raw);$det=$be-eq 0-and$me-ne 0-and$raw.Contains($f[3]);Set-Content (Join-Path $d result.txt) "Detected=$det`nExpectedFailureTag=$($f[3])`nObservedFailureTags=$raw";$rows+= "$id`t$($f[0])`tMutationVerifier`t$($f[0])`t$($f[1])->$($f[2])`t$be`t$me`t$($f[3])`t$raw`t$det" }
$defs=@(@('37','real-execution-readiness.txt','ExecutableReadyReal=0','ExecutableReadyReal=1','ExecutableReadyReal'),@('38','control-link-summary.txt','fatalDiagnostics=0','fatalDiagnostics=1','FatalDiagnostics'))
foreach($f in $defs){$id=$f[0];$d=Join-Path $WorkRoot "mutation\cases\$id";$base=Join-Path $d baseline;$mut=Join-Path $d mutation;New-Item -Force -ItemType Directory $base,$mut|Out-Null;Run (Join-Path $audit 'SemanticVerifier.ps1') @('-WorkRoot',$WorkRoot) $base|Out-Null;$be=[int](Get-Content (Join-Path $base exit.txt));$p=Join-Path $WorkRoot "audit\$($f[1])";$z=(Get-Content $p -Raw).Replace($f[2],$f[3]);[IO.File]::WriteAllText($p,$z);Run (Join-Path $audit 'SemanticVerifier.ps1') @('-WorkRoot',$WorkRoot) $mut|Out-Null;$me=[int](Get-Content (Join-Path $mut exit.txt));$raw=(Get-Content (Join-Path $mut stdout.txt)-Raw)+(Get-Content (Join-Path $mut stderr.txt)-Raw);$det=$be-eq 0-and$me-ne 0-and$raw.Contains($f[4]);$rows+="$id`tSemanticVerifier`t$($f[1])`t$($f[2])->$($f[3])`t$be`t$me`t$($f[4])`t$raw`t$det"}
